/// The character drawn in place of this one in right-to-left text.
pub(crate) fn mirror_of(code: u32) -> Option<u32> {
    MIRRORS.binary_search_by_key(&code, |(from, _)| *from).ok().map(|at| MIRRORS[at].1)
}

